$(function(){$("[data-report-column-sum='[data-table-column=total]']").removeClass("text-center");$("body").on("change","input[data-type='int'], input[data-type='float']",function(){$("[data-type='int'], [data-type='float']").each(function(){if($(this).val()=="")$(this).val(0)});var _table_rows=$("table.dynamic.table-INVENTORY tbody tr");var total_rs=0;_table_rows.each(function(){var qty=NumberHelper.parseInput($("[data-js='qty']",this));var rate=NumberHelper.parseInput($("[data-js='rate']",this));var row_total=qty*rate;total_rs+=row_total;$("[data-table-column='total']",this).html(NumberHelper.thousandSep(NumberHelper.round(row_total)))});$("[data-report-column-sum='[data-table-column=total]']").html(NumberHelper.thousandSep(total_rs))});setTimeout(function(){$("input[data-type='float']:first-child").trigger("change")},500)});